window.AUTH=window.AUTH||{};window.AUTH["86-595"]={"d":"86-595","id":"1987/86-595","n":"United States v. Fausto","src":["osg"],"briefs":[{"k":"reply","label":"Reply brief for the United States","date":"","url":"https://www.justice.gov/osg/media/219211/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/united-states-america-petitioner-v-joseph-fausto-0","toa":false,"n":31},{"k":"respondent","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/205151/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/united-states-america-petitioner-v-joseph-fausto","toa":false,"n":70}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep484/usrep484439/usrep484439.pdf","tr":false,"items":[{"t":"case","label":"Chu v. United States","cite":"773 F.2d 1226","url":"https://www.courtlistener.com/c/F.2d/773/1226/","by":{"0":"","1":""}},{"t":"case","label":"Harrison v. Bowen","cite":"815 F.2d 1505","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/815/1505/","by":{"0":""}},{"t":"case","label":"Cook County Nat'l Bank v. United States","cite":"107 U.S. 445","y":1882,"id":"scdb/1882-191","sc":1,"sum":"This is an appeal from a decree of the Circuit Court overruling a general demurrer to a bill filed by the United States against the Cook County National Bank of Chicago, 111., and Augustus H. Burley, its receiver. The facts, as stated in the bill, are briefly as follows: Previously to 1872, the bank was formed under the acts of Congress authorizing the organization of national banks, and was designated as a …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Bush v. Lucas","cite":"462 U.S. 367","y":1983,"id":"1982/81-469","sc":1,"sum":"Not under the CSC regulations. The federal judiciary, pursuant to its common law authority, has the power to recognize new causes of action in absence of, or to supplement, statutory remedies unless Congress has expressly indicated its relief is to be exclusive.","sumSrc":"Oyez","by":{"0":"","1":""}},{"t":"case","label":"United States v. Testan","cite":"424 U.S. 392","y":1976,"id":"1975/74-753","sc":1,"op":1,"sum":"Respondent Government trial attorneys with civil service grade GS-13 classifications requested their employing agency to reclassify their positions to grade GS-14, contending that their duties and responsibilities met the requirements for the higher grade and were identical to those of other trial attorneys classified as GS-14 in another agency, and that under the principle of \"equal pay for substantially equal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Bowen v. Michigan Academy of Family Physicians","cite":"476 U.S. 567","y":1986,"id":"1985/85-225","sc":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Block v. Community Nutrition Institute","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"op":7,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Spagnola v. Mathis","cite":"809 F.2d 16","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/809/16/","by":{"0":"","1":""}},{"t":"case","label":"Rosano v. United States","cite":"800 F.2d 1126","y":1986,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/800/1126/","by":{"0":"","1":""}},{"t":"case","label":"Carducci v. Regan","cite":"714 F.2d 171","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/714/171/","op":1,"by":{"0":"","1":""}},{"t":"case","label":"McClary v. United States","cite":"775 F.2d 280","y":1985,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/775/280/","by":{"0":"","1":""}},{"t":"case","label":"Veit v. Heckler","cite":"746 F.2d 508","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/746/508/","by":{"0":"","1":""}},{"t":"case","label":"United States v. Connolly","cite":"716 F.2d 882","y":1983,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/716/882/","by":{"0":"","1":""}},{"t":"case","label":"Fiorentino v. United States","cite":"607 F.2d 963","y":1979,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/607/963/","by":{"0":""}},{"t":"case","label":"Brown v. GSA","cite":"425 U.S. 820","y":1976,"id":"1975/74-768","sc":1,"sum":"Section 717 provides the exBROWN v. GSA","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"op":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Vitarelli v. Seaton","cite":"359 U.S. 535","y":1959,"id":"1958/101","sc":1,"op":4,"sum":"Petitioner's dismissal was illegal and he is entitled to reinstatement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"Service v. Dulles","cite":"354 U.S. 363","y":1957,"id":"1956/407","sc":1,"op":16,"sum":"Petitioner's discharge was invalid, because it violated Regulations of the Department of State which were binding on the Secretary; and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"","1":""}},{"t":"case","label":"United Steelworkers v. Enterprise Wheel & Car Corp.","cite":"363 U.S. 593","y":1960,"id":"1959/538","sc":1,"sum":"The judgment of the District Court should have been affirmed with a modification requiring the specific amounts due the employees to be definitely determined by arbitration.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"usc","label":"5 U.S.C. § 7702","url":"https://www.law.cornell.edu/uscode/text/5/7702","by":{"0":"","1":""}},{"t":"usc","label":"5 U.S.C. § 2302","url":"https://www.law.cornell.edu/uscode/text/5/2302","stext":{"head":"§2302. Prohibited personnel practices","paras":[[0,"(a)(1) For the purpose of this title, \"prohibited personnel practice\" means any action described in subsection (b)."],[0,"(2) For the purpose of this section—"],[1,"(A) \"personnel action\" means—"],[2,"(i) an appointment;"],[2,"(ii) a promotion;"],[2,"(iii) an action under chapter 75 of this title or other disciplinary or corrective action;"],[2,"(iv) a detail, transfer, or reassignment;"],[2,"(v) a reinstatement;"],[2,"(vi) a restoration;"],[2,"(vii) a reemployment;"],[2,"(viii) a performance evaluation under chapter 43 of this title or under title 38;"],[2,"(ix) a decision concerning pay, benefits, or awards, or concerning education or training if the education or training may reasonably be expected to lead to an appointment, promotion, performance evaluation, or other action described in this subparagraph;"],[2,"(x) a decision to order psychiatric testing or examination;"],[2,"(xi) the implementation or enforcement of any nondisclosure policy, form, or agreement; and"],[2,"(xii) any other significant change in duties, responsibilities, or working conditions;"],[1,"with respect to an employee in, or applicant for, a covered position in an agency, and in the case of an alleged prohibited personnel practice described in subsection (b)(8), an employee or applicant for employment in a Government corporation as defined in section 9101 of title 31;"],[1,"(B) \"covered position\" means, with respect to any personnel action, any position in the competitive service, a career appointee position in the Senior Executive Service, or a position in the excepted service, but does not include any position which is, prior to the personnel action—"],[2,"(i) excepted from the competitive service because of its confidential, policy-determining, policy-making, or policy-advocating character; or"],[2,"(ii) excluded from the coverage of this section by the President based on a determination by the President that it is necessary and warranted by conditions of good administration;"],[1,"(C) \"agency\" means an Executive agency and the Government Publishing Office, but does not include—"],[2,"(i) a Government corporation, except in the case of an alleged prohibited personnel practice described under subsection (b)(8) or section 2302(b)(9)(A)(i), (B), (C), or (D);"],[2,"(ii)(I) the Federal Bureau of Investigation, the Central Intelligence Agency, the Defense Intelligence Agency, the National Geospatial-Intelligence Agency, the National Security Agency, the Office of the Director of National Intelligence, and the National Reconnaissance Office; and"],[2,"(II) as determined by the President, any executive agency or unit thereof the principal function of which is the conduct of foreign intelligence or counterintelligence activities, provided that the determination be made prior to a personnel action; or"],[2,"(iii) the Government Accountability Office; and"],[1,"(D) \"disclosure\" means a formal or informal communication or transmission, but does not include a communication concerning policy decisions that lawfully exercise discretionary authority unless the employee or applicant providing the disclosure reasonably believes that the disclosure evidences—"],[2,"(i) any violation of any law, rule, or regulation; or"],[2,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety."],[0,"(b) Any employee who has authority to take, direct others to take, recommend, or approve any personnel action, shall not, with respect to such authority—"],[1,"(1) discriminate for or against any employee or applicant for employment—"],[2,"(A) on the basis of race, color, religion, sex, or national origin, as prohibited under section 717 of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16);"],[2,"(B) on the basis of age, as prohibited under sections 12 and 15 of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 631, 633a);"],[2,"(C) on the basis of sex, as prohibited under section 6(d) of the Fair Labor Standards Act of 1938 (29 U.S.C. 206(d));"],[2,"(D) on the basis of handicapping condition, as prohibited under section 501 of the Rehabilitation Act of 1973 (29 U.S.C. 791); or"],[2,"(E) on the basis of marital status or political affiliation, as prohibited under any law, rule, or regulation;"],[1,"(2) solicit or consider any recommendation or statement, oral or written, with respect to any individual who requests or is under consideration for any personnel action unless such recommendation or statement is based on the personal knowledge or records of the person furnishing it and consists of—"],[2,"(A) an evaluation of the work performance, ability, aptitude, or general qualifications of such individual; or"],[2,"(B) an evaluation of the character, loyalty, or suitability of such individual;"],[1,"(3) coerce the political activity of any person (including the providing of any political contribution or service), or take any action against any employee or applicant for employment as a reprisal for the refusal of any person to engage in such political activity;"],[1,"(4) deceive or willfully obstruct any person with respect to such person's right to compete for employment;"],[1,"(5) influence any person to withdraw from competition for any position for the purpose of improving or injuring the prospects of any other person for employment;"],[1,"(6) grant any preference or advantage not authorized by law, rule, or regulation to any employee or applicant for employment (including defining the scope or manner of competition or the requirements for any position) for the purpose of improving or injuring the prospects of any particular person for employment;"],[1,"(7) appoint, employ, promote, advance, or advocate for appointment, employment, promotion, or advancement, in or to a civilian position any individual who is a relative (as defined in section 3110(a)(3) of this title) of such employee if such position is in the agency in which such employee is serving as a public official (as defined in section 3110(a)(2) of this title) or over which such employee exercises jurisdiction or control as such an official;"],[1,"(8) take or fail to take, or threaten to take or fail to take, a personnel action with respect to any employee or applicant for employment because of—"],[2,"(A) any disclosure of information by an employee or applicant which the employee or applicant reasonably believes evidences—"],[3,"(i) any violation of any law, rule, or regulation, or"],[3,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety,"],[2,"if such disclosure is not specifically prohibited by law and if such information is not specifically required by Executive order to be kept secret in the interest of national defense or the conduct of foreign affairs;"],[2,"(B) any disclosure to the Special Counsel, or to the Inspector General of an agency or another employee designated by the head of the agency to receive such disclosures, of information which the employee or applicant reasonably believes evidences—"],[3,"(i) any violation (other than a violation of this section) of any law, rule, or regulation, or"],[3,"(ii) gross mismanagement, a gross waste of funds, an abuse of authority, or a substantial and specific danger to public health or safety; or"],[2,"(C) any disclosure to Congress (including any committee of Congress) by any employee of an agency or applicant for employment at an agency of information described in subparagraph (B) that is—"],[3,"(i) not classified; or"],[3,"(ii) if classified—"],[4,"(I) has been classified by the head of an agency that is not an element of the intelligence community (as defined by section 3 of the National Security Act of 1947 (50 U.S.C. 3003)); and"],[4,"(II) does not reveal intelligence sources and methods.1"],[1,"(9) take or fail to take, or threaten to take or fail to take, any personnel action against any employee or applicant for employment because of—"],[2,"(A) the exercise of any appeal, complaint, or grievance right granted by any law, rule, or regulation—"],[3,"(i) with regard to remedying a violation of paragraph (8); or"],[3,"(ii) other than with regard to remedying a violation of paragraph (8);"],[2,"(B) testifying for or otherwise lawfully assisting any individual in the exercise of any right referred to in subparagraph (A)(i) or (ii);"],[2,"(C) cooperating with or disclosing information to the Inspector General (or any other component responsible for internal investigation or review) of an agency, or the Special Counsel, in accordance with applicable provisions of law; or"],[2,"(D) refusing to obey an order that would require the individual to violate a law, rule, or regulation;"],[1,"(10) discriminate for or against any employee or applicant for employment on the basis of conduct which does not adversely affect the performance of the employee or applicant or the performance of others; except that nothing in this paragraph shall prohibit an agency from taking into account in determining suitability or fitness any conviction of the employee or applicant for any crime under the laws of any State, of the District of Columbia, or of the United States;"],[1,"(11)(A) knowingly take, recommend, or approve any personnel action if the taking of such action would violate a veterans' preference requirement; or"],[1,"(B) knowingly fail to take, recommend, or approve any personnel action if the failure to take such action would violate a veterans' preference requirement;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/2302?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2302. Prohibited personnel practices","tname":"Government Organization and Employees","by":{"0":"","1":""}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","stext":{"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","paras":[[0,"(a)(1) The United States Court of Federal Claims shall have jurisdiction to render judgment upon any claim against the United States founded either upon the Constitution, or any Act of Congress or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(2) To provide an entire remedy and to complete the relief afforded by the judgment, the court may, as an incident of and collateral to any such judgment, issue orders directing restoration to office or position, placement in appropriate duty or retirement status, and correction of applicable records, and such orders may be issued to any appropriate official of the United States. In any case within its jurisdiction, the court shall have the power to remand appropriate matters to any administrative or executive body or official with such direction as it may deem proper and just. The Court of Federal Claims shall have jurisdiction to render judgment upon any claim by or against, or dispute with, a contractor arising under section 7104(b)(1) of title 41, including a dispute concerning termination of a contract, rights in tangible or intangible property, compliance with cost accounting standards, and other nonmonetary disputes on which a decision of the contracting officer has been issued under section 6 1 of that Act."],[0,"(b)(1) Both the Unites 2 States Court of Federal Claims and the district courts of the United States shall have jurisdiction to render judgment on an action by an interested party objecting to a solicitation by a Federal agency for bids or proposals for a proposed contract or to a proposed award or the award of a contract or any alleged violation of statute or regulation in connection with a procurement or a proposed procurement. Both the United States Court of Federal Claims and the district courts of the United States shall have jurisdiction to entertain such an action without regard to whether suit is instituted before or after the contract is awarded."],[0,"(2) To afford relief in such an action, the courts may award any relief that the court considers proper, including declaratory and injunctive relief except that any monetary relief shall be limited to bid preparation and proposal costs."],[0,"(3) In exercising jurisdiction under this subsection, the courts shall give due regard to the interests of national defense and national security and the need for expeditious resolution of the action."],[0,"(4) In any action under this subsection, the courts shall review the agency's decision pursuant to the standards set forth in section 706 of title 5."],[0,"(5) If an interested party who is a member of the private sector commences an action described in paragraph (1) with respect to a public-private competition conducted under Office of Management and Budget Circular A–76 regarding the performance of an activity or function of a Federal agency, or a decision to convert a function performed by Federal employees to private sector performance without a competition under Office of Management and Budget Circular A–76, then an interested party described in section 3551(2)(B) of title 31 shall be entitled to intervene in that action."],[0,"(6) Jurisdiction over any action described in paragraph (1) arising out of a maritime contract, or a solicitation for a proposed maritime contract, shall be governed by this section and shall not be subject to the jurisdiction of the district courts of the United States under the Suits in Admiralty Act (chapter 309 of title 46) or the Public Vessels Act (chapter 311 of title 46)."],[0,"(c) Nothing herein shall be construed to give the United States Court of Federal Claims jurisdiction of any civil action within the exclusive jurisdiction of the Court of International Trade, or of any action against, or founded on conduct of, the Tennessee Valley Authority, or to amend or modify the provisions of the Tennessee Valley Authority Act of 1933 with respect to actions by or against the Authority."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1491?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","tname":"Judiciary and Judicial Procedure","by":{"0":"","1":""}},{"t":"usc","label":"5 U.S.C. § 5596","url":"https://www.law.cornell.edu/uscode/text/5/5596","subs":["(b)(1)"],"stext":{"head":"§5596. Back pay due to unjustified personnel action","paras":[[0,"(a) For the purpose of this section, \"agency\" means—"],[1,"(1) an Executive agency;"],[1,"(2) the Administrative Office of the United States Courts, the Federal Judicial Center, and the courts named by section 610 of title 28;"],[1,"(3) the Library of Congress;"],[1,"(4) the Government Publishing Office;"],[1,"(5) the government of the District of Columbia;"],[1,"(6) the Architect of the Capitol, including employees of the United States Senate Restaurants; and"],[1,"(7) the United States Botanic Garden."],[0,"(b)(1) An employee of an agency who, on the basis of a timely appeal or an administrative determination (including a decision relating to an unfair labor practice or a grievance) is found by appropriate authority under applicable law, rule, regulation, or collective bargaining agreement, to have been affected by an unjustified or unwarranted personnel action which has resulted in the withdrawal or reduction of all or part of the pay, allowances, or differentials of the employee—"],[1,"(A) is entitled, on correction of the personnel action, to receive for the period for which the personnel action was in effect—"],[2,"(i) an amount equal to all or any part of the pay, allowances, or differentials, as applicable which the employee normally would have earned or received during the period if the personnel action had not occurred, less any amounts earned by the employee through other employment during that period; and"],[2,"(ii) reasonable attorney fees related to the personnel action which, with respect to any decision relating to an unfair labor practice or a grievance processed under a procedure negotiated in accordance with chapter 71 of this title, or under chapter 11 of title I of the Foreign Service Act of 1980, shall be awarded in accordance with standards established under section 7701(g) of this title; and"],[1,"(B) for all purposes, is deemed to have performed service for the agency during that period, except that—"],[2,"(i) annual leave restored under this paragraph which is in excess of the maximum leave accumulation permitted by law shall be credited to a separate leave account for the employee and shall be available for use by the employee within the time limits prescribed by regulations of the Office of Personnel Management, and"],[2,"(ii) annual leave credited under clause (i) of this subparagraph but unused and still available to the employee under regulations prescribed by the Office shall be included in the lump-sum payment under section 5551 or 5552(1) of this title but may not be retained to the credit of the employee under section 5552(2) of this title."],[0,"(2)(A) An amount payable under paragraph (1)(A)(i) of this subsection shall be payable with interest."],[0,"(B) Such interest—"],[1,"(i) shall be computed for the period beginning on the effective date of the withdrawal or reduction involved and ending on a date not more than 30 days before the date on which payment is made;"],[1,"(ii) shall be computed at the rate or rates in effect under section 6621(a)(1) of the Internal Revenue Code of 1986 during the period described in clause (i); and"],[1,"(iii) shall be compounded daily."],[0,"(C) Interest under this paragraph shall be paid out of amounts available for payments under paragraph (1) of this subsection."],[0,"(3) This subsection does not apply to any reclassification action nor authorize the setting aside of an otherwise proper promotion by a selecting official from a group of properly ranked and certified candidates."],[0,"(4) The pay, allowances, or differentials granted under this section for the period for which an unjustified or unwarranted personnel action was in effect shall not exceed that authorized by the applicable law, rule, regulations, or collective bargaining agreement under which the unjustified or unwarranted personnel action is found, except that in no case may pay, allowances, or differentials be granted under this section for a period beginning more than 6 years before the date of the filing of a timely appeal or, absent such filing, the date of the administrative determination."],[0,"(5) For the purpose of this subsection, \"grievance\" and \"collective bargaining agreement\" have the meanings set forth in section 7103 of this title and (with respect to members of the Foreign Service) in sections 1101 and 1002 of the Foreign Service Act of 1980, \"unfair labor practice\" means an unfair labor practice described in section 7116 of this title and (with respect to members of the Foreign Service) in section 1015 of the Foreign Service Act of 1980, and \"personnel action\" includes the omission or failure to take an action or confer a benefit."],[0,"(c) The Office of Personnel Management shall prescribe regulations to carry out this section. However, the regulations are not applicable to the Tennessee Valley Authority and its employees, or to the agencies specified in subsection (a)(2) of this section."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/5596?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§5596. Back pay due to unjustified personnel action","tname":"Government Organization and Employees","by":{"0":"","1":""}},{"t":"usc","label":"42 U.S.C. § 1985","url":"https://www.law.cornell.edu/uscode/text/42/1985","subs":["(1)"],"by":{"0":"","1":""}},{"t":"usc","label":"5 U.S.C. § 7511","url":"https://www.law.cornell.edu/uscode/text/5/7511","subs":["(c)"],"stext":{"head":"§7511. Definitions; application","paras":[[0,"(a) For the purpose of this subchapter—"],[1,"(1) \"employee\" means—"],[2,"(A) an individual in the competitive service—"],[3,"(i) who is not serving a probationary or trial period under an initial appointment; or"],[3,"(ii) who has completed 1 year of current continuous service under other than a temporary appointment limited to 1 year or less;"],[2,"(B) a preference eligible in the excepted service who has completed 1 year of current continuous service in the same or similar positions—"],[3,"(i) in an Executive agency; or"],[3,"(ii) in the United States Postal Service or Postal Regulatory Commission; and"],[2,"(C) an individual in the excepted service (other than a preference eligible)—"],[3,"(i) who is not serving a probationary or trial period under an initial appointment pending conversion to the competitive service; or"],[3,"(ii) who has completed 2 years of current continuous service in the same or similar positions in an Executive agency under other than a temporary appointment limited to 2 years or less;"],[1,"(2) \"suspension\" has the same meaning as set forth in section 7501(2) of this title;"],[1,"(3) \"grade\" means a level of classification under a position classification system;"],[1,"(4) \"pay\" means the rate of basic pay fixed by law or administrative action for the position held by an employee; and"],[1,"(5) \"furlough\" means the placing of an employee in a temporary status without duties and pay because of lack of work or funds or other nondisciplinary reasons."],[0,"(b) This subchapter does not apply to an employee—"],[1,"(1) whose appointment is made by and with the advice and consent of the Senate;"],[1,"(2) whose position has been determined to be of a confidential, policy-determining, policy-making or policy-advocating character by—"],[2,"(A) the President for a position that the President has excepted from the competitive service;"],[2,"(B) the Office of Personnel Management for a position that the Office has excepted from the competitive service; or"],[2,"(C) the President or the head of an agency for a position excepted from the competitive service by statute;"],[1,"(3) whose appointment is made by the President;"],[1,"(4) who is receiving an annuity from the Civil Service Retirement and Disability Fund, or the Foreign Service Retirement and Disability Fund, based on the service of such employee;"],[1,"[(5) Repealed. Pub. L. 114–328, div. A, title V, §512(c), Dec. 23, 2016, 130 Stat. 2112.]"],[1,"(6) who is a member of the Foreign Service, as described in section 103 of the Foreign Service Act of 1980;"],[1,"(7) whose position is within the Central Intelligence Agency or the Government Accountability Office;"],[1,"(8) whose position is within the United States Postal Service, the Postal Regulatory Commission, the Panama Canal Commission, the Tennessee Valley Authority, the Federal Bureau of Investigation, an intelligence component of the Department of Defense (as defined in section 1614 of title 10), or an intelligence activity of a military department covered under subchapter I of chapter 83 of title 10, unless subsection (a)(1)(B) of this section or section 1005(a) of title 39 is the basis for this subchapter's applicability;"],[1,"(9) who is described in section 5102(c)(11) of this title; or"],[1,"(10) who holds a position within the Veterans Health Administration which has been excluded from the competitive service by or under a provision of title 38, unless such employee was appointed to such position under section 7401(3) of such title."],[0,"(c) The Office may provide for the application of this subchapter to any position or group of positions excepted from the competitive service by regulation of the Office which is not otherwise covered by this subchapter."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7511?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7511. Definitions; application","tname":"Government Organization and Employees","by":{"0":"","1":""}},{"t":"usc","label":"5 U.S.C. § 4301","url":"https://www.law.cornell.edu/uscode/text/5/4301","subs":["(2)"],"stext":{"head":"§4301. Definitions","paras":[[0,"Except as otherwise expressly provided, for the purpose of this subchapter—"],[1,"(1) \"agency\" means—"],[2,"(A) an Executive agency; and"],[2,"(B) the Government Publishing Office;"],[1,"but does not include—"],[2,"(i) a Government corporation;"],[2,"(ii) the Central Intelligence Agency, the Defense Intelligence Agency, the National Geospatial-Intelligence Agency, the National Security Agency, or any Executive agency or unit thereof which is designated by the President and the principal function of which is the conduct of foreign intelligence or counterintelligence activities; or"],[2,"(iii) the Government Accountability Office;"],[1,"(2) \"employee\" means an individual employed in or under an agency, but does not include—"],[2,"(A) an employee outside the United States who is paid in accordance with local native prevailing wage rates for the area in which employed;"],[2,"(B) an individual in the Foreign Service of the United States;"],[2,"(C) a physician, dentist, nurse, or other employee in the Veterans Health Administration of the Department of Veterans Affairs whose pay is fixed under chapter 73 of title 38;"],[2,"(D) an administrative law judge appointed under section 3105 of this title;"],[2,"(E) an individual in the Senior Executive Service or the Federal Bureau of Investigation and Drug Enforcement Administration Senior Executive Service;"],[2,"(F) an individual appointed by the President;"],[2,"(G) an individual occupying a position not in the competitive service excluded from coverage of this subchapter by regulations of the Office of Personnel Management; or"],[2,"(H) an individual who (i) is serving in a position under a temporary appointment for less than one year, (ii) agrees to serve without a performance evaluation, and (iii) will not be considered for a reappointment or for an increase in pay based in whole or in part on performance; and"],[1,"(3) \"unacceptable performance\" means performance of an employee which fails to meet established performance standards in one or more critical elements of such employee's position."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/4301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4301. Definitions","tname":"Government Organization and Employees","by":{"0":"","1":""}},{"t":"usc","label":"5 U.S.C. § 4303","url":"https://www.law.cornell.edu/uscode/text/5/4303","subs":["(e)"],"stext":{"head":"§4303. Actions based on unacceptable performance","paras":[[0,"(a) Subject to the provisions of this section, an agency may reduce in grade or remove an employee for unacceptable performance."],[0,"(b)(1) An employee whose reduction in grade or removal is proposed under this section is entitled to—"],[1,"(A) 30 days' advance written notice of the proposed action which identifies—"],[2,"(i) specific instances of unacceptable performance by the employee on which the proposed action is based; and"],[2,"(ii) the critical elements of the employee's position involved in each instance of unacceptable performance;"],[1,"(B) be represented by an attorney or other representative;"],[1,"(C) a reasonable time to answer orally and in writing; and"],[1,"(D) a written decision which—"],[2,"(i) in the case of a reduction in grade or removal under this section, specifies the instances of unacceptable performance by the employee on which the reduction in grade or removal is based, and"],[2,"(ii) unless proposed by the head of the agency, has been concurred in by an employee who is in a higher position than the employee who proposed the action."],[0,"(2) An agency may, under regulations prescribed by the head of such agency, extend the notice period under subsection (b)(1)(A) of this section for not more than 30 days. An agency may extend the notice period for more than 30 days only in accordance with regulations issued by the Office of Personnel Management."],[0,"(c) The decision to retain, reduce in grade, or remove an employee—"],[1,"(1) shall be made within 30 days after the date of expiration of the notice period, and"],[1,"(2) in the case of a reduction in grade or removal, may be based only on those instances of unacceptable performance by the employee—"],[2,"(A) which occurred during the 1-year period ending on the date of the notice under subsection (b)(1)(A) of this section in connection with the decision; and"],[2,"(B) for which the notice and other requirements of this section are complied with."],[0,"(d) If, because of performance improvement by the employee during the notice period, the employee is not reduced in grade or removed, and the employee's performance continues to be acceptable for 1 year from the date of the advance written notice provided under subsection (b)(1)(A) of this section, any entry or other notation of the unacceptable performance for which the action was proposed under this section shall be removed from any agency record relating to the employee."],[0,"(e) Any employee who is—"],[1,"(1) a preference eligible;"],[1,"(2) in the competitive service; or"],[1,"(3) in the excepted service and covered by subchapter II of chapter 75,"],[0,"and who has been reduced in grade or removed under this section is entitled to appeal the action to the Merit Systems Protection Board under section 7701."],[0,"(f) This section does not apply to—"],[1,"(1) the reduction to the grade previously held of a supervisor or manager who has not completed the probationary period under section 3321(a)(2) of this title,"],[1,"(2) the reduction in grade or removal of an employee in the competitive service who is serving a probationary or trial period under an initial appointment or who has not completed 1 year of current continuous employment under other than a temporary appointment limited to 1 year or less,"],[1,"(3) the reduction in grade or removal of an employee in the excepted service who has not completed 1 year of current continuous employment in the same or similar positions, or"],[1,"(4) any removal or demotion under section 714 of title 38."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/4303?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§4303. Actions based on unacceptable performance","tname":"Government Organization and Employees","by":{"0":"","1":""}},{"t":"usc","label":"5 U.S.C. § 2103","url":"https://www.law.cornell.edu/uscode/text/5/2103","subs":["(a)"],"stext":{"head":"§2103. The excepted service","paras":[[0,"(a) For the purpose of this title, the \"excepted service\" consists of those civil service positions which are not in the competitive service or the Senior Executive Service."],[0,"(b) As used in other Acts of Congress, \"unclassified civil service\" or \"unclassified service\" means the \"excepted service\"."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/2103?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2103. The excepted service","tname":"Government Organization and Employees","by":{"0":"","1":""}},{"t":"usc","label":"28 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/28/1361","by":{"0":"","1":""}},{"t":"usc","label":"25 U.S.C. § 472","url":"https://www.law.cornell.edu/uscode/text/25/472","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","op":1,"by":{"0":""}},{"t":"case","label":"Fausto v. Department of Interior","cite":"738 F.2d 454","y":1984,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/738/454/","op":1,"by":{"1":""}},{"t":"case","label":"Smith v. MSPB","cite":"813 F.2d 1216","y":1987,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/813/1216/","op":32,"by":{"1":""}},{"t":"case","label":"Bulova Watch Co. v. United States","cite":"365 U.S. 753","y":1961,"id":"1960/241","sc":1,"sum":"When the Court of Claims has awarded a judgment against the United States to a taxpayer for an overpayment of excess profits taxes, plus interest thereon \"as provided by law,\" determination of the allowance of interest on so much of the overpayment as was attributable to an unused excess profits credit carry-back is governed by § 3771 (e) of the Internal Revenue Code of 1939, dealing specifically with interest on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Pinar v. Dole","cite":"747 F.2d 899","y":1984,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/747/899/","op":1,"by":{"1":""}},{"t":"case","label":"Lindahl v. OPM","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"op":5,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Polcover v. Secretary of Treasury","cite":"477 F.2d 1223","url":"https://www.courtlistener.com/c/F.2d/477/1223/","op":1,"by":{"1":""}},{"t":"case","label":"Wathen v. United States","cite":"527 F.2d 1191","y":1975,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/527/1191/","by":{"1":""}},{"t":"case","label":"Cornelius v. Nutt","cite":"472 U.S. 648","y":1985,"id":"1984/83-1673","sc":1,"sum":"Under §7701(c)(2)(A), the employee-grievant must show error that caused substantial prejudice to his individual rights by possibly affecting the agency's decision.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"CSRA. In Schwartz v. Department of Transportation","cite":"714 F.2d 1581","y":1983,"url":"https://www.courtlistener.com/c/F.2d/714/1581/","by":{"1":""}},{"t":"case","label":"Borrell v. United States International Communications Agency","cite":"682 F.2d 981","y":1982,"url":"https://www.courtlistener.com/c/F.2d/682/981/","by":{"1":""}},{"t":"case","label":"Cutts v. Fowler","cite":"692 F.2d 138","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/692/138/","by":{"1":""}},{"t":"case","label":"Broadway v. Block","cite":"694 F.2d 979","y":1982,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/694/979/","by":{"1":""}},{"t":"case","label":"Fowler v. United States","cite":"633 F.2d 1258","y":1980,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/633/1258/","by":{"1":""}},{"t":"case","label":"Lovshin v. Department of Navy","cite":"767 F.2d 826","y":1985,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/767/826/","by":{"1":""}},{"t":"case","label":"United States v. Erika, Inc.","cite":"456 U.S. 201","y":1982,"id":"1981/80-1594","sc":1,"op":4,"sum":"The Court of Claims has no jurisdiction to review determinations by private insurance carriers of the amount of benefits payable under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":""}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Federal Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"op":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"Kotarski v. Cooper","cite":"799 F.2d 1342","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/799/1342/","by":{"1":""}},{"t":"case","label":"Hubbard v. EPA","cite":"809 F.2d 1","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/809/1/","by":{"1":""}},{"t":"case","label":"Weatherford v. Dole","cite":"763 F.2d 392","y":1985,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/763/392/","by":{"1":""}},{"t":"case","label":"Burroughs v. OPM","cite":"764 F.2d 1300","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/764/1300/","by":{"1":""}},{"t":"case","label":"Barnhart v. Devine","cite":"771 F.2d 1515","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/771/1515/","by":{"1":""}},{"t":"case","label":"CSRA. In Dugan v. Ramsay","cite":"727 F.2d 192","y":1984,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/727/192/","by":{"1":""}},{"t":"case","label":"Cleveland Board of Education v. Loudermill","cite":"470 U.S. 532","y":1985,"id":"1984/83-1362","sc":1,"op":1,"sum":"The Court found that \"affording the employee an opportunity to respond prior to termination would impose neither a significant administrative burden nor intolerable delays.\" Accordingly, the significant interests of the employees to retain their jobs outweighed the interests of the state to remove employees quickly.","sumSrc":"Oyez","by":{"1":""}},{"t":"case","label":"Hadley Memorial Hospital, Inc. v. Schweiker","cite":"689 F.2d 905","y":1982,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/689/905/","by":{"1":""}},{"t":"case","label":"Jones v. Alexander","cite":"613 F.2d 314","url":"https://www.courtlistener.com/c/F.2d/613/314/","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 2102","url":"https://www.law.cornell.edu/uscode/text/5/2102","stext":{"head":"§2102. The competitive service","paras":[[0,"(a) The \"competitive service\" consists of—"],[1,"(1) all civil service positions in the executive branch, except—"],[2,"(A) positions which are specifically excepted from the competitive service by or under statute;"],[2,"(B) positions to which appointments are made by nomination for confirmation by the Senate, unless the Senate otherwise directs; and"],[2,"(C) positions in the Senior Executive Service;"],[1,"(2) civil service positions not in the executive branch which are specifically included in the competitive service by statute; and"],[1,"(3) positions in the government of the District of Columbia which are specifically included in the competitive service by statute."],[0,"(b) Notwithstanding subsection (a)(1)(B) of this section, the \"competitive service\" includes positions to which appointments are made by nomination for confirmation by the Senate when specifically included therein by statute."],[0,"(c) As used in other Acts of Congress, \"classified civil service\" or \"classified service\" means the \"competitive service\"."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/2102?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2102. The competitive service","tname":"Government Organization and Employees","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 3132","url":"https://www.law.cornell.edu/uscode/text/5/3132","subs":["(a)(2)"],"stext":{"head":"§3132. Definitions and exclusions","paras":[[0,"(a) For the purpose of this subchapter—"],[1,"(1) \"agency\" means an Executive agency, except a Government corporation and the Government Accountability Office, but does not include—"],[2,"(A) any agency or unit thereof excluded from coverage by the President under subsection (c) of this section; or"],[2,"(B) the Federal Bureau of Investigation, the Drug Enforcement Administration, the Central Intelligence Agency, the Office of the Director of National Intelligence, the Defense Intelligence Agency, the National Geospatial-Intelligence Agency, the National Security Agency, Department of Defense intelligence activities the civilian employees of which are subject to section 1590 of title 10, and, as determined by the President, an Executive agency, or unit thereof, whose principal function is the conduct of foreign intelligence or counterintelligence activities;"],[2,"(C) the Federal Election Commission or the Election Assistance Commission;"],[2,"(D) the Office of the Comptroller of the Currency, the Office of Thrift Supervision,,1 the Resolution Trust Corporation, the Farm Credit Administration, the Federal Housing Finance Agency, the National Credit Union Administration, the Bureau of Consumer Financial Protection, and the Office of Financial Research;"],[2,"(E) the Securities and Exchange Commission; or"],[2,"(F) the Commodity Futures Trading Commission;"],[1,"(2) \"Senior Executive Service position\" means any position in an agency which is classified above GS–15 pursuant to section 5108 or in level IV or V of the Executive Schedule, or an equivalent position, which is not required to be filled by an appointment by the President by and with the advice and consent of the Senate, and in which an employee—"],[2,"(A) directs the work of an organizational unit;"],[2,"(B) is held accountable for the success of one or more specific programs or projects;"],[2,"(C) monitors progress toward organizational goals and periodically evaluates and makes appropriate adjustments to such goals;"],[2,"(D) supervises the work of employees other than personal assistants; or"],[2,"(E) otherwise exercises important policy-making, policy-determining, or other executive functions;"],[1,"but does not include—"],[2,"(i) any position in the Foreign Service of the United States;"],[2,"(ii) an administrative law judge position under section 3105 of this title;"],[2,"(iii) any position established as a qualified position in the excepted service by the Secretary of Homeland Security under section 226 2 of the Homeland Security Act of 2002; or"],[2,"(iv) any position established as a qualified position in the excepted service by the Secretary of Defense under section 1599f of title 10;"],[1,"(3) \"senior executive\" means a member of the Senior Executive Service;"],[1,"(4) \"career appointee\" means an individual in a Senior Executive Service position whose appointment to the position or previous appointment to another Senior Executive Service position was based on approval by the Office of Personnel Management of the executive qualifications of such individual;"],[1,"(5) \"limited term appointee\" means an individual appointed under a nonrenewable appointment for a term of 3 years or less to a Senior Executive Service position the duties of which will expire at the end of such term;"],[1,"(6) \"limited emergency appointee\" means an individual appointed under a nonrenewable appointment, not to exceed 18 months, to a Senior Executive Service position established to meet a bona fide, unanticipated, urgent need;"],[1,"(7) \"noncareer appointee\" means an individual in a Senior Executive Service position who is not a career appointee, a limited term appointee, or a limited emergency appointee;"],[1,"(8) \"career reserved position\" means a position which is required to be filled by a career appointee and which is designated under subsection (b) of this section; and"],[1,"(9) \"general position\" means any position, other than a career reserved position, which may be filled by either a career appointee, noncareer appointee, limited emergency appointee, or limited term appointee."],[0,"(b)(1) For the purpose of paragraph (8) of subsection (a) of this section, the Office shall prescribe the criteria and regulations governing the designation of career reserved positions. The criteria and regulations shall provide that a position shall be designated as a career reserved position only if the filling of the position by a career appointee is necessary to ensure impartiality, or the public's confidence in the impartiality, of the Government. The head of each agency shall be responsible for designating career reserved positions in such agency in accordance with such criteria and regulations."],[0,"(2) The Office shall periodically review general positions to determine whether the positions should be designated as career reserved. If the Office determines that any such position should be so designated, it shall order the agency to make the designation."],[0,"(3) Notwithstanding the provisions of any other law, any position to be designated as a Senior Executive Service position (except a position in the Executive Office of the President) which—"],[1,"(A) is under the Executive Schedule, or for which the rate of basic pay is determined by reference to the Executive Schedule, and"],[1,"(B) on the day before the date of the enactment of the Civil Service Reform Act of 1978 was specifically required under section 2102 of this title or otherwise required by law to be in the competitive service,"],[0,"shall be designated as a career reserved position if the position entails direct responsibility to the public for the management or operation of particular government programs or functions."],[0,"(4) Not later than March 1 of each year, the head of each agency shall publish in the Federal Register a list of positions in the agency which were career reserved positions during the preceding calendar year."],[0,"(c) An agency may file an application with the Office setting forth reasons why it, or a unit thereof, should be excluded from the coverage of this subchapter. The Office shall—"],[1,"(1) review the application and stated reasons,"],[1,"(2) undertake a review to determine whether the agency or unit should be excluded from the coverage of this subchapter, and"],[1,"(3) upon completion of its review, recommend to the President whether the agency or unit should be excluded from the coverage of this subchapter."],[0,"If the Office recommends that an agency or unit thereof be excluded from the coverage of this subchapter, the President may, on written determination, make the exclusion for the period determined by the President to be appropriate."],[0,"(d) Any agency or unit which is excluded from coverage under subsection (c) of this section shall make a sustained effort to bring its personnel system into conformity with the Senior Executive Service to the extent practicable."],[0,"(e) The Office may at any time recommend to the President that any exclusion previously granted to an agency or unit thereof under subsection (c) of this section be revoked. Upon recommendation of the Office, the President may revoke, by written determination, any exclusion made under subsection (c) of this section."],[0,"(f) If—"],[1,"(1) any agency is excluded under subsection (c) of this section, or"],[1,"(2) any exclusion is revoked under subsection (e) of this section,"],[0,"the Office shall, within 30 days after the action, transmit to the Congress written notice of the exclusion or revocation."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/3132?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3132. Definitions and exclusions","tname":"Government Organization and Employees","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(d)"],"by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"1":""}},{"t":"usc","label":"28 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/28/2201","by":{"1":""}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/5/1104","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 1205","url":"https://www.law.cornell.edu/uscode/text/5/1205","stext":{"head":"§1205. Transmittal of information to Congress","paras":[[0,"Notwithstanding any other provision of law or any rule, regulation or policy directive, any member of the Board, or any employee of the Board designated by the Board, may transmit to the Congress on the request of any committee or subcommittee thereof, by report, testimony, or otherwise, information and views on functions, responsibilities, or other matters relating to the Board, without review, clearance, or approval by any other administrative authority."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/1205?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1205. Transmittal of information to Congress","tname":"Government Organization and Employees","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 7701","url":"https://www.law.cornell.edu/uscode/text/5/7701","subs":["(c)(2)(A)"],"stext":{"head":"§7701. Appellate procedures","paras":[[0,"(a) An employee, or applicant for employment, may submit an appeal to the Merit Systems Protection Board from any action which is appealable to the Board under any law, rule, or regulation. An appellant shall have the right—"],[1,"(1) to a hearing for which a transcript will be kept; and"],[1,"(2) to be represented by an attorney or other representative."],[0,"Appeals shall be processed in accordance with regulations prescribed by the Board."],[0,"(b)(1) The Board may hear any case appealed to it or may refer the case to an administrative law judge appointed under section 3105 of this title or other employee of the Board designated by the Board to hear such cases, except that in any case involving a removal from the service, the case shall be heard by the Board, an employee experienced in hearing appeals, or an administrative law judge. The Board, administrative law judge, or other employee (as the case may be) shall make a decision after receipt of the written representations of the parties to the appeal and after opportunity for a hearing under subsection (a)(1) of this section. A copy of the decision shall be furnished to each party to the appeal and to the Office of Personnel Management."],[0,"(2)(A) If an employee or applicant for employment is the prevailing party in an appeal under this subsection, the employee or applicant shall be granted the relief provided in the decision effective upon the making of the decision, and remaining in effect pending the outcome of any petition for review under subsection (e), unless—"],[1,"(i) the deciding official determines that the granting of such relief is not appropriate; or"],[1,"(ii)(I) the relief granted in the decision provides that such employee or applicant shall return or be present at the place of employment during the period pending the outcome of any petition for review under subsection (e); and"],[1,"(II) the employing agency, subject to the provisions of subparagraph (B), determines that the return or presence of such employee or applicant is unduly disruptive to the work environment."],[0,"(B) If an agency makes a determination under subparagraph (A)(ii)(II) that prevents the return or presence of an employee at the place of employment, such employee shall receive pay, compensation, and all other benefits as terms and conditions of employment during the period pending the outcome of any petition for review under subsection (e)."],[0,"(C) Nothing in the provisions of this paragraph may be construed to require any award of back pay or attorney fees be paid before the decision is final."],[0,"(3) With respect to an appeal from an adverse action covered by subchapter V of chapter 75, authority to mitigate the personnel action involved shall be available, subject to the same standards as would apply in an appeal involving an action covered by subchapter II of chapter 75 with respect to which mitigation authority under this section exists."],[0,"(c)(1) Subject to paragraph (2) of this subsection, the decision of the agency shall be sustained under subsection (b) only if the agency's decision—"],[1,"(A) in the case of an action based on unacceptable performance described in section 4303, is supported by substantial evidence; or"],[1,"(B) in any other case, is supported by a preponderance of the evidence."],[0,"(2) Notwithstanding paragraph (1), the agency's decision may not be sustained under subsection (b) of this section if the employee or applicant for employment—"],[1,"(A) shows harmful error in the application of the agency's procedures in arriving at such decision;"],[1,"(B) shows that the decision was based on any prohibited personnel practice described in section 2302(b) of this title; or"],[1,"(C) shows that the decision was not in accordance with law."],[0,"(d)(1) In any case in which—"],[1,"(A) the interpretation or application of any civil service law, rule, or regulation, under the jurisdiction of the Office of Personnel Management is at issue in any proceeding under this section; and"],[1,"(B) the Director of the Office of Personnel Management is of the opinion that an erroneous decision would have a substantial impact on any civil service law, rule, or regulation under the jurisdiction of the Office;"],[0,"the Director may as a matter of right intervene or otherwise participate in that proceeding before the Board. If the Director exercises his right to participate in a proceeding before the Board, he shall do so as early in the proceeding as practicable. Nothing in this title shall be construed to permit the Office to interfere with the independent decisionmaking of the Merit Systems Protection Board."],[0,"(2) The Board shall promptly notify the Director whenever the interpretation of any civil service law, rule, or regulation under the jurisdiction of the Office is at issue in any proceeding under this section."],[0,"(e)(1) Except as provided in section 7702 of this title, any decision under subsection (b) of this section shall be final unless—"],[1,"(A) a party to the appeal or the Director petitions the Board for review within 30 days after the receipt of the decision; or"],[1,"(B) the Board reopens and reconsiders a case on its own motion."],[0,"The Board, for good cause shown, may extend the 30-day period referred to in subparagraph (A) of this paragraph. One member of the Board may grant a petition or otherwise direct that a decision be reviewed by the full Board. The preceding sentence shall not apply if, by law, a decision of an administrative law judge is required to be acted upon by the Board."],[0,"(2) The Director may petition the Board for a review under paragraph (1) of this subsection only if the Director is of the opinion that the decision is erroneous and will have a substantial impact on any civil service law, rule, or regulation under the jurisdiction of the Office."],[0,"(f) The Board, or an administrative law judge or other employee of the Board designated to hear a case, may—"],[1,"(1) consolidate appeals filed by two or more appellants, or"],[1,"(2) join two or more appeals filed by the same appellant and hear and decide them concurrently,"],[0,"if the deciding official or officials hearing the cases are of the opinion that the action could result in the appeals' being processed more expeditiously and would not adversely affect any party."],[0,"(g)(1) Except as provided in paragraph (2) of this subsection, the Board, or an administrative law judge or other employee of the Board designated to hear a case, may require payment by the agency involved of reasonable attorney fees incurred by an employee or applicant for employment if the employee or applicant is the prevailing party and the Board, administrative law judge, or other employee (as the case may be) determines that payment by the agency is warranted in the interest of justice, including any case in which a prohibited personnel practice was engaged in by the agency or any case in which the agency's action was clearly without merit."],[0,"(2) If an employee or applicant for employment is the prevailing party and the decision is based on a finding of discrimination prohibited under section 2302(b)(1) of this title, the payment of attorney fees shall be in accordance with the standards prescribed under section 706(k) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–5(k))."],[0,"(h) The Board may, by regulation, provide for one or more alternative methods for settling matters subject to the appellate jurisdiction of the Board which shall be applicable at the election of an applicant for employment or of an employee who is not in a unit for which a labor organization is accorded exclusive recognition, and shall be in lieu of other procedures provided for under this section. A decision under such a method shall be final, unless the Board reopens and reconsiders a case at the request of the Office of Personnel Management under subsection (e) of this section."],[0,"(i)(1) Upon the submission of any appeal to the Board under this section, the Board, through reference to such categories of cases, or other means, as it determines appropriate, shall establish and announce publicly the date by which it intends to complete action on the matter. Such date shall assure expeditious consideration of the appeal, consistent with the interests of fairness and other priorities of the Board. If the Board fails to complete action on the appeal by the announced date, and the expected delay will exceed 30 days, the Board shall publicly announce the new date by which it intends to complete action on the appeal."],[0,"(2) Not later than March 1 of each year, the Board shall submit to the Congress a report describing the number of appeals submitted to it during the preceding fiscal year, the number of appeals on which it completed action during that year, and the number of instances during that year in which it failed to conclude a proceeding by the date originally announced, together with an explanation of the reasons therefor."],[0,"(3) The Board shall by rule indicate any other category of significant Board action which the Board determines should be subject to the provisions of this subsection."],[0,"(4) It shall be the duty of the Board, an administrative law judge, or employee designated by the Board to hear any proceeding under this section to expedite to the extent practicable that proceeding."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7701?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§7701. Appellate procedures","tname":"Government Organization and Employees","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 1206","url":"https://www.law.cornell.edu/uscode/text/5/1206","stext":{"head":"§1206. Annual report","paras":[[0,"The Board shall submit an annual report to the President and the Congress on its activities, which shall include a description of significant actions taken by the Board to carry out its functions under this title. The report shall also review the significant actions of the Office of Personnel Management, including an analysis of whether the actions of the Office of Personnel Management are in accord with merit system principles and free from prohibited personnel practices."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/1206?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1206. Annual report","tname":"Government Organization and Employees","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","stext":{"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","paras":[[0,"(a)(1) Any employee or applicant for employment adversely affected or aggrieved by a final order or decision of the Merit Systems Protection Board may obtain judicial review of the order or decision."],[0,"(2) The Board shall be named respondent in any proceeding brought pursuant to this subsection, unless the employee or applicant for employment seeks review of a final order or decision on the merits on the underlying personnel action or on a request for attorney fees, in which case the agency responsible for taking the personnel action shall be the respondent."],[0,"(b)(1)(A) Except as provided in subparagraph (B) and paragraph (2) of this subsection, a petition to review a final order or final decision of the Board shall be filed in the United States Court of Appeals for the Federal Circuit. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(B) A petition to review a final order or final decision of the Board that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D) shall be filed in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(2) Cases of discrimination subject to the provisions of section 7702 of this title shall be filed under section 717(c) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16(c)), section 15(c) of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a(c)), and section 16(b) of the Fair Labor Standards Act of 1938, as amended (29 U.S.C. 216(b)), as applicable. Notwithstanding any other provision of law, any such case filed under any such section must be filed within 30 days after the date the individual filing the case received notice of the judicially reviewable action under such section 7702."],[0,"(c) In any case filed in the United States Court of Appeals for the Federal Circuit, the court shall review the record and hold unlawful and set aside any agency action, findings, or conclusions found to be—"],[1,"(1) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(2) obtained without procedures required by law, rule, or regulation having been followed; or"],[1,"(3) unsupported by substantial evidence;"],[0,"except that in the case of discrimination brought under any section referred to in subsection (b)(2) of this section, the employee or applicant shall have the right to have the facts subject to trial de novo by the reviewing court."],[0,"(d)(1) Except as provided under paragraph (2), this paragraph shall apply to any review obtained by the Director of the Office of Personnel Management. The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the Court of Appeals. The granting of the petition for judicial review shall be at the discretion of the Court of Appeals."],[0,"(2) This paragraph shall apply to any review obtained by the Director of the Office of Personnel Management that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D). The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the court of appeals. The granting of the petition for judicial review shall be at the discretion of the court of appeals."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7703?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","tname":"Government Organization and Employees","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 7501","url":"https://www.law.cornell.edu/uscode/text/5/7501","subs":["(1)"],"stext":{"head":"§7501. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"employee\" means an individual in the competitive service who is not serving a probationary or trial period under an initial appointment or who has completed 1 year of current continuous employment in the same or similar positions under other than a temporary appointment limited to 1 year or less; and"],[1,"(2) \"suspension\" means the placing of an employee, for disciplinary reasons, in a temporary status without duties and pay."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/7501?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7501. Definitions","tname":"Government Organization and Employees","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 1204","url":"https://www.law.cornell.edu/uscode/text/5/1204","by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(1)"],"by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 3301","url":"https://www.law.cornell.edu/uscode/text/5/3301","by":{"1":""}},{"t":"usc","label":"31 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/31/1349","subs":["(b)"],"op":1,"by":{"1":""}},{"t":"usc","label":"5 U.S.C. § 2108","url":"https://www.law.cornell.edu/uscode/text/5/2108","subs":["(3)"],"stext":{"head":"§2108. Veteran; disabled veteran; preference eligible","paras":[[0,"For the purpose of this title—"],[1,"(1) \"veteran\" means an individual who—"],[2,"(A) served on active duty in the armed forces during a war, in a campaign or expedition for which a campaign badge has been authorized, or during the period beginning April 28, 1952, and ending July 1, 1955;"],[2,"(B) served on active duty as defined by section 101(21) of title 38 at any time in the armed forces for a period of more than 180 consecutive days any part of which occurred after January 31, 1955, and before October 15, 1976, not including service under section 12103(d) of title 10 pursuant to an enlistment in the Army National Guard or the Air National Guard or as a Reserve for service in the Army Reserve, Navy Reserve, Air Force Reserve, Marine Corps Reserve, or Coast Guard Reserve;"],[2,"(C) served on active duty as defined by section 101(21) of title 38 in the armed forces during the period beginning on August 2, 1990, and ending on January 2, 1992; or"],[2,"(D) served on active duty as defined by section 101(21) of title 38 at any time in the armed forces for a period of more than 180 consecutive days any part of which occurred during the period beginning on September 11, 2001, and ending on the date prescribed by Presidential proclamation or by law as the last date of Operation Iraqi Freedom;"],[1,"and, except as provided under section 2108a, who has been discharged or released from active duty in the armed forces under honorable conditions;"],[1,"(2) \"disabled veteran\" means an individual who has served on active duty in the armed forces, (except as provided under section 2108a) has been separated therefrom under honorable conditions, and has established the present existence of a service-connected disability or is receiving compensation, disability retirement benefits, or pension because of a public statute administered by the Department of Veterans Affairs or a military department;"],[1,"(3) \"preference eligible\" means, except as provided in paragraph (4) of this section or section 2108a(c)—"],[2,"(A) a veteran as defined by paragraph (1)(A) of this section;"],[2,"(B) a veteran as defined by paragraph (1)(B), (C), or (D) of this section;"],[2,"(C) a disabled veteran;"],[2,"(D) the unmarried widow or widower of a veteran as defined by paragraph (1)(A) of this section;"],[2,"(E) the wife or husband of a service-connected disabled veteran if the veteran has been unable to qualify for any appointment in the civil service or in the government of the District of Columbia;"],[2,"(F) the parent of an individual who lost his or her life under honorable conditions while serving in the armed forces during a period named by paragraph (1)(A) of this section, if—"],[3,"(i) the spouse of that parent is totally and permanently disabled; or"],[3,"(ii) that parent, when preference is claimed, is unmarried or, if married, legally separated from his or her spouse;"],[2,"(G) the parent of a service-connected permanently and totally disabled veteran, if—"],[3,"(i) the spouse of that parent is totally and permanently disabled; or"],[3,"(ii) that parent, when preference is claimed, is unmarried or, if married, legally separated from his or her spouse; and"],[2,"(H) a veteran who was discharged or released from a period of active duty by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10);"],[1,"but does not include applicants for, or members of, the Senior Executive Service, the Defense Intelligence Senior Executive Service, the Senior Cryptologic Executive Service, or the Federal Bureau of Investigation and Drug Enforcement Administration Senior Executive Service;"],[1,"(4) except for the purposes of chapters 43 and 75 of this title, \"preference eligible\" does not include a retired member of the armed forces unless—"],[2,"(A) the individual is a disabled veteran; or"],[2,"(B) the individual retired below the rank of major or its equivalent; and"],[1,"(5) \"retired member of the armed forces\" means a member or former member of the armed forces who is entitled, under statute, to retired, retirement, or retainer pay on account of service as a member."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/2108?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2108. Veteran; disabled veteran; preference eligible","tname":"Government Organization and Employees","by":{"1":""}},{"t":"usc","label":"29 U.S.C. § 633a","url":"https://www.law.cornell.edu/uscode/text/29/633a","subs":["(c)"],"by":{"1":""}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)"],"by":{"1":""}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","subs":["(d)"],"by":{"1":""}}]};